/*
 * MegaNetBookingAd — Online appointment booking, a feature-spotlight ad for Mega-Net EHR Cloud. 1080x1920 @30fps.
 * 0.4s lead-in, voice 27.44s, 2s frozen hold after the voice (see src/bookingTimings.ts).
 * Voice: public/voiceover-booking.mp3 (en-NG-EzinneNeural, a per-feature voice choice; the series default is AbeoNeural),
 * word timings in src/bookingTimings.ts (both generated by scripts/booking_voice.py). No music, no sound effects.
 *
 * Look: light and airy (STYLE_GUIDE.md). Brand blue #1A6DE0 + orange #F7941D on near-white / pale blue / pale peach
 * gradients, white cards, charcoal text. Red marks only the "busy" state, green only the "booked" state.
 *
 * Hook: "phone icon morph". A ringing phone icon (shaking handset tile, ring arcs, blinking drawn busy bars) morphs, in
 * one continuous shape change, into a booking card with a tick; a "Booked" pill lands on it. Different from the questions
 * (ERP/EHR), the staccato statements (Sentinel), the typed field (Assistant), the trail line (Ledger), the calendar-flip
 * story (P&L), the command stamp (Cash Flow), the viewfinder (Balance Sheet) and the collision (Pharmacy).
 * Transitions (new for the series, all clip-path/mask reveals that never move text): square-tile cascade, alternating
 * horizontal slats, polka-dot reveal, reverse tile cascade.
 *
 * Safe area: all content inside x 80-920, y 200-1440; captions end at y=1272 (limit 1280); content ends by y 1095 (24px above
 * the two-line caption zone y 1120-1272). Every scene lives in a clip box of exactly the safe area.
 *
 * Everything on screen is a concept drawing: no screenshots, nothing from the live Northgate demo, no names, no figures
 * except "60 days" (the configured public booking window, EHR-Cloud- meganet/settings.py:526). Branch tiles carry their own
 * drawn link chip; nothing shows a staff screen handing a link out. See BOOKING_AD_SCRIPT.md for the claim map.
 *
 * Debug input prop (verification only): 'bg' = gradients only, 'caps' = captions only, 'nocaps' = scene content without
 * captions, 'violate-*' / 'violateweak-left' = negative controls, 'audit' = logs every text node's box/colour/size,
 * 'notext' = same frame with text made transparent.
 */
import React, {useEffect, useState} from 'react';
import {AbsoluteFill, Audio, Easing, Freeze, Img, Sequence, continueRender, delayRender, interpolate, interpolateColors, staticFile, useCurrentFrame} from 'remotion';
import {LINES, VOICE_END} from './bookingTimings';
import {CaptionViolation, DebugContext, Icon as FxIcon, Layer, GradientBg, Glow} from './fx';

export const BK_FPS = 30;
const LEAD = 12; // 0.4s before the voice starts
const FREEZE = LEAD + Math.round(VOICE_END * BK_FPS); // last frame with any motion
export const BK_DURATION = FREEZE + 2 * BK_FPS; // hold 2s after the voice ends

const BLUE = '#1A6DE0';
const ORANGE = '#F7941D';
const GREEN = '#12875A';
const RED = '#D8383D';
const TEAL = '#0E9AA7';
const TXT_BLUE = '#1458B5';
const TXT_ORANGE = '#9E3F00';
const TXT_GREEN = '#0B6E46';
const TXT_RED = '#B42328';
const TXT_TEAL = '#0A6A74';
const INK = '#1B2430';
const MUTED = '#44506A';
const WHITE = '#FFFFFF';
const LINE = '#C9DCF6';
const PLACE = '#D0D5E4'; // drawn placeholder bars (no text on them)
const FONT = 'Inter, "Inter Display", system-ui, sans-serif';

const COL_L = 110;
const COL_W = 780; // x 110-890, inside the 80-920 safe area
const SAFE = {x: 80, y: 200, w: 840, h: 1240};
const CLIP_H = 896; // scene clip box is y 200-1096, 24px above the caption zone (y 1120-1272)
const CX = 540;

const wordF = (s: number, w: number) => LEAD + Math.round(LINES[s].words[w].start * BK_FPS);
const wordEndF = (s: number, w: number) => LEAD + Math.round(LINES[s].words[w].end * BK_FPS);
const TR = 16; // transition length in frames

// Visual scenes. The hook (V0) spans narration lines 0 and 1: the phone morphs into the booking card as "Mega-Net" is spoken.
// V0 hook | V1 branches (line 2) | V2 days and times (line 3) | V3 booked page + list (line 4) | V4 call to action (line 5)
const VS = [0, 2, 3, 4, 5]; // first narration line of each visual scene
const sceneFrom = (i: number) => (i === 0 ? 0 : wordF(VS[i], 0) - 9);
const LAST = VS.length - 1;
const sceneTo = (i: number) => (i === LAST ? BK_DURATION : sceneFrom(i + 1) + TR);

const ease = Easing.out(Easing.cubic);
const back = Easing.out(Easing.back(1.4));
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const enter = (f: number, start: number, dur = 9) => interpolate(f, [start, start + dur], [0, 1], {easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
const rise = (v: number) => `translateY(${(1 - v) * 30}px)`;

/* ---------- transitions: clip-path reveals only (the incoming scene is masked in; text never moves) ---------- */

type Trans = 'tiles' | 'rows' | 'dots' | 'tilesr';
const TRANS: (Trans | null)[] = [null, 'tiles', 'rows', 'dots', 'tilesr'];
const COLS = 8;
const ROWS = 9;
const GX = 80;
const GY = 200;
const CW = 840 / COLS; // 105
const CH = 900 / ROWS; // 100
const raw = (f: number, from: number) => clamp01((f - from) / TR);

const TransClip: React.FC<{id: string; t: Trans; r: number}> = ({id, t, r}) => {
  const e = ease(r);
  const shapes: React.ReactNode[] = [];
  if (t === 'rows') {
    for (let k = 0; k < ROWS; k++) {
      const s = clamp01((e - (k / (ROWS - 1)) * 0.4) / 0.6);
      const w = 841 * s;
      shapes.push(<rect key={k} x={k % 2 === 0 ? GX : GX + 840 - w} y={GY + k * CH - 0.5} width={w} height={CH + 1} />);
    }
  } else {
    for (let i = 0; i < COLS; i++) {
      for (let j = 0; j < ROWS; j++) {
        const cx = GX + (i + 0.5) * CW;
        const cy = GY + (j + 0.5) * CH;
        if (t === 'dots') {
          const d = Math.hypot(i - (COLS - 1) / 2, j - (ROWS - 1) / 2) / Math.hypot((COLS - 1) / 2, (ROWS - 1) / 2);
          const s = clamp01((e - d * 0.5) / 0.5);
          shapes.push(<circle key={`${i}-${j}`} cx={cx} cy={cy} r={80 * s} />);
        } else {
          const order = t === 'tiles' ? i + j : COLS - 1 - i + (ROWS - 1 - j);
          const s = clamp01((e - (order / (COLS + ROWS - 2)) * 0.5) / 0.5);
          shapes.push(<rect key={`${i}-${j}`} x={cx - (CW * 1.04 * s) / 2} y={cy - (CH * 1.04 * s) / 2} width={CW * 1.04 * s} height={CH * 1.04 * s} />);
        }
      }
    }
  }
  return (
    <svg width={0} height={0} style={{position: 'absolute'}}>
      <defs>
        <clipPath id={id} clipPathUnits="userSpaceOnUse">
          {shapes}
        </clipPath>
      </defs>
    </svg>
  );
};

const bgStyle = (i: number, r: number): React.CSSProperties => (i === 0 ? {} : {opacity: ease(r)});

/* ---------- backgrounds: one distinct light gradient per visual scene (full bleed, content-free) ---------- */

const g = (x: number, y: number, r: number, color: string, drift = 30): Glow => ({x, y, r, color, drift});
const BGS: {stops: string[]; angle: number; glows: Glow[]}[] = [
  {stops: ['#FFFFFF', '#EAF4FF', '#FFF1DC'], angle: 165, glows: [g(900, 420, 460, 'rgba(26,109,224,0.16)'), g(170, 1500, 500, 'rgba(247,148,29,0.18)')]},
  {stops: ['#EAF4FF', '#D3E6FF', '#FFF2DE'], angle: 190, glows: [g(160, 430, 450, 'rgba(26,109,224,0.16)'), g(920, 1480, 500, 'rgba(247,148,29,0.14)')]},
  {stops: ['#FFF8EE', '#FFE6C4', '#E2EEFF'], angle: 150, glows: [g(900, 420, 440, 'rgba(14,154,167,0.12)'), g(150, 1520, 500, 'rgba(247,148,29,0.26)')]},
  {stops: ['#E6F6EF', '#EAF4FF', '#FFF3E0'], angle: 170, glows: [g(200, 420, 460, 'rgba(18,135,90,0.14)'), g(900, 1450, 500, 'rgba(26,109,224,0.16)')]},
  {stops: ['#D4E6FF', '#FFF3E0', '#FFC584'], angle: 150, glows: [g(200, 380, 460, 'rgba(255,255,255,0.55)'), g(900, 1450, 500, 'rgba(247,148,29,0.28)')]},
];

const Backgrounds: React.FC = () => {
  const f = useCurrentFrame();
  return (
    <AbsoluteFill>
      {BGS.map((b, i) => {
        const from = sceneFrom(i);
        if (f < from) return null;
        const r = i === 0 ? 1 : raw(f, from);
        return (
          <Sequence key={i} from={from} durationInFrames={BK_DURATION - from} layout="none">
            <AbsoluteFill style={bgStyle(i, r)}>
              <GradientBg stops={b.stops} angle={b.angle} glows={b.glows} />
            </AbsoluteFill>
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};

/* ---------- small drawn pieces ---------- */

type GlyphName = 'phone' | 'globe' | 'check' | 'building' | 'link' | 'user' | 'key' | 'arrowdown' | 'clock' | 'noentry';
const Glyph: React.FC<{name: GlyphName; size?: number; color?: string; stroke?: number}> = ({name, size = 48, color = '#fff', stroke = 2.4}) => {
  const paths: Record<GlyphName, React.ReactNode> = {
    phone: <path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z" />,
    globe: (
      <>
        <circle cx="12" cy="12" r="9" />
        <path d="M3 12h18 M12 3c3 3 3 15 0 18 M12 3c-3 3-3 15 0 18" />
      </>
    ),
    check: <path d="M5 13l4 4L19 7" />,
    building: <path d="M4 21V8l8-5 8 5v13z M9 21v-6h6v6 M8 11h2 M14 11h2" />,
    link: <path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1 M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1" />,
    user: (
      <>
        <circle cx="12" cy="8" r="4" />
        <path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7" />
      </>
    ),
    key: (
      <>
        <circle cx="8" cy="12" r="4" />
        <path d="M12 12h9 M18 12v4 M15 12v3" />
      </>
    ),
    arrowdown: <path d="M12 4v15 M6 13l6 6 6-6" />,
    clock: (
      <>
        <circle cx="12" cy="12" r="9" />
        <path d="M12 7v5l3 2" />
      </>
    ),
    noentry: (
      <>
        <circle cx="12" cy="12" r="9" />
        <path d="M5.6 5.6l12.8 12.8" />
      </>
    ),
  };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" style={{display: 'block'}}>
      {paths[name]}
    </svg>
  );
};

const Tile: React.FC<{color: string; size: number; radius?: number; children: React.ReactNode}> = ({color, size, radius = size * 0.3, children}) => (
  <div style={{width: size, height: size, borderRadius: radius, background: color, display: 'flex', alignItems: 'center', justifyContent: 'center', flex: 'none'}}>{children}</div>
);

const LogoCard: React.FC<{width: number; pad: number; radius: number}> = ({width, pad, radius}) => (
  <div style={{background: WHITE, borderRadius: radius, padding: pad, border: `3px solid ${LINE}`, boxShadow: '0 10px 24px rgba(26,80,160,0.16)', display: 'inline-flex'}}>
    <Img src={staticFile('logo-trim.jpg')} style={{width, height: 'auto', display: 'block'}} />
  </div>
);

const Bar: React.FC<{w: number | string; h?: number; color?: string}> = ({w, h = 26, color = PLACE}) => (
  <div style={{width: w, height: h, borderRadius: h / 2, background: color, flex: 'none'}} />
);

const Card: React.FC<{style?: React.CSSProperties; children?: React.ReactNode}> = ({style, children}) => (
  <div style={{position: 'absolute', left: COL_L, width: COL_W, background: WHITE, borderRadius: 36, border: `3px solid ${LINE}`, boxShadow: '0 12px 28px rgba(26,80,160,0.16)', boxSizing: 'border-box', ...style}}>{children}</div>
);

/** Badge and feature label, fully visible from frame 0 (no entry animation). */
const Header: React.FC<{f: number}> = ({f}) => {
  const pulseAt = wordF(1, 0); // "Mega-Net" is spoken: the badge rings once
  const pr = clamp01((f - pulseAt) / 16);
  return (
    <>
      <div style={{position: 'absolute', left: COL_L, width: COL_W, top: 216, display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
        <LogoCard width={180} pad={12} radius={26} />
        <div style={{position: 'relative', display: 'flex', alignItems: 'center', gap: 14, background: WHITE, border: `3px solid ${LINE}`, borderRadius: 44, padding: '10px 28px 10px 14px', color: INK, fontSize: 32, fontWeight: 800}}>
          <Tile color={ORANGE} size={50} radius={16}>
            <FxIcon name="notebook" size={36} accent={BLUE} ink={WHITE} />
          </Tile>
          Mega-Net EHR Cloud
          {pr > 0 && pr < 1 && <div style={{position: 'absolute', left: -3 - 14 * pr, top: -3 - 14 * pr, right: -3 - 14 * pr, bottom: -3 - 14 * pr, borderRadius: 60, border: `5px solid ${ORANGE}`, opacity: 1 - pr}} />}
        </div>
      </div>
      <div style={{position: 'absolute', left: COL_L, width: COL_W, top: 322, display: 'flex', justifyContent: 'center'}}>
        <div style={{display: 'flex', alignItems: 'center', gap: 10, background: WHITE, border: `3px solid ${LINE}`, borderRadius: 40, padding: '8px 30px', fontSize: 34, fontWeight: 800, color: INK, whiteSpace: 'nowrap'}}>
          <span style={{color: TXT_ORANGE}}>Feature:</span> Online appointment booking
        </div>
      </div>
    </>
  );
};

/** One visual scene: lives in a clip box of exactly the safe area, entering through a clip-path reveal. */
const SceneFrame: React.FC<{i: number; header?: boolean; children: (f: number) => React.ReactNode}> = ({i, header = true, children}) => {
  const f = useCurrentFrame();
  const from = sceneFrom(i);
  const to = sceneTo(i);
  if (f < from || f >= to) return null;
  const t = TRANS[i];
  const reveal = i > 0 && t && f < from + TR;
  const id = `tr-${i}`;
  return (
    <Layer kind="content">
      <div style={{position: 'absolute', left: SAFE.x, top: SAFE.y, width: SAFE.w, height: CLIP_H, overflow: 'hidden'}}>
        <div style={{position: 'absolute', left: -SAFE.x, top: -SAFE.y, width: 1080, height: 1920, clipPath: reveal ? `url(#${id})` : undefined}}>
          {reveal && t && <TransClip id={id} t={t} r={raw(f, from)} />}
          {header && <Header f={f} />}
          {children(f)}
        </div>
      </div>
    </Layer>
  );
};

/* ---------- scene V0 (hook): ringing phone, busy bars, morph into a booking card ---------- */

const HERO_CY = 700;
const BUSY_ON_FROM = 22;

const Hook: React.FC<{f: number}> = ({f}) => {
  const m = ease(clamp01((f - 128) / 36)); // morph progress, 128-164: starts as "again" ends, done before "Mega-Net" finishes
  const ringing = f < 128;
  const shake = ringing ? Math.sin(f * 1.35) * 7 * (f > 3 ? 1 : f / 3) : 0;
  const tileW = interpolate(m, [0, 1], [360, 700]);
  const tileH = interpolate(m, [0, 1], [360, 460]);
  const left = CX - tileW / 2;
  const top = interpolate(m, [0, 1], [520, 452]);
  const radius = interpolate(m, [0, 1], [110, 40]);
  const bg = interpolateColors(m, [0, 1], [BLUE, WHITE]);
  const borderCol = interpolateColors(m, [0, 1], [BLUE, LINE]);
  const phoneO = 1 - clamp01(m / 0.45);
  const cardO = clamp01((m - 0.55) / 0.45);
  const arcs = ringing ? (Math.floor(f / 9) % 3) : -1; // 0..2 arcs lit in turn
  const busyIn = enter(f, BUSY_ON_FROM - 6, 8) * (1 - clamp01((f - 124) / 10));
  const busyOn = Math.floor((f - BUSY_ON_FROM) / 7) % 2 === 0;
  const pill = enter(f, wordF(1, 5), 10); // "book"
  const tick = back(enter(f, wordF(1, 5) + 2, 12));
  return (
    <>
      {/* ring arcs, top-right and top-left of the handset tile */}
      {ringing && f > 3 && (
        <svg width={760} height={200} viewBox="0 0 760 200" style={{position: 'absolute', left: CX - 380, top: 410, overflow: 'visible'}}>
          {[0, 1, 2].map((k) => {
            const on = arcs >= k;
            const rr = 36 + k * 30;
            return (
              <g key={k} opacity={on ? 1 : 0.18}>
                <path d={`M${380 + 230 + rr} ${150 - rr * 0.9} A${rr} ${rr} 0 0 1 ${380 + 230 + rr} ${150 + rr * 0.1}`} fill="none" stroke={ORANGE} strokeWidth={14} strokeLinecap="round" />
                <path d={`M${380 - 230 - rr} ${150 - rr * 0.9} A${rr} ${rr} 0 0 0 ${380 - 230 - rr} ${150 + rr * 0.1}`} fill="none" stroke={ORANGE} strokeWidth={14} strokeLinecap="round" />
              </g>
            );
          })}
        </svg>
      )}
      {/* the morphing shape: handset tile -> booking card */}
      <div style={{position: 'absolute', left, top, width: tileW, height: tileH, borderRadius: radius, background: bg, border: `3px solid ${borderCol}`, boxSizing: 'border-box', boxShadow: '0 14px 32px rgba(26,80,160,0.22)', transform: `rotate(${shake}deg)`, }}>
        <div style={{position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: phoneO, transform: `scale(${1 - 0.35 * m})`}}>
          <Glyph name="phone" size={210} stroke={2.2} />
        </div>
        <div style={{position: 'absolute', inset: 0, opacity: cardO, padding: 0}}>
          <div style={{height: 88, borderRadius: '37px 37px 0 0', background: BLUE, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 120}}>
            <div style={{width: 18, height: 44, borderRadius: 9, background: WHITE}} />
            <div style={{width: 18, height: 44, borderRadius: 9, background: WHITE}} />
          </div>
          <div style={{display: 'grid', gridTemplateColumns: 'repeat(5, 88px)', gap: 18, justifyContent: 'center', padding: '28px 0 0'}}>
            {Array.from({length: 15}).map((_, k) => (
              <div key={k} style={{height: 56, borderRadius: 16, background: k === 7 ? ORANGE : '#E3ECFA', display: 'flex', alignItems: 'center', justifyContent: 'center', transform: k === 7 ? `scale(${0.6 + 0.4 * tick})` : undefined}}>
                {k === 7 && <Glyph name="check" size={40} stroke={3.4} />}
              </div>
            ))}
          </div>
        </div>
      </div>
      {/* drawn busy bars (no sound): blink while the phone rings, then clear as the card forms */}
      {busyIn > 0.01 && (
        <div style={{position: 'absolute', left: CX - 190, top: 920, width: 380, height: 70, display: 'flex', justifyContent: 'space-between', alignItems: 'center', opacity: busyIn}}>
          {Array.from({length: 6}).map((_, k) => (
            <div key={k} style={{width: 44, height: 70, borderRadius: 14, background: busyOn ? RED : '#EBC9CB'}} />
          ))}
        </div>
      )}
      {/* "Booked" lands on the morphed card as "book" is spoken */}
      <div style={{position: 'absolute', left: COL_L, width: COL_W, top: 960, display: 'flex', justifyContent: 'center', opacity: pill, transform: `translateY(${(1 - back(pill)) * -30}px)`}}>
        <div style={{display: 'flex', alignItems: 'center', gap: 18, background: TXT_GREEN, borderRadius: 52, padding: '14px 44px 14px 26px', color: WHITE, fontSize: 52, fontWeight: 900, boxShadow: '0 12px 26px rgba(11,110,70,0.32)'}}>
          <Glyph name="check" size={52} stroke={3.2} />
          Booked
        </div>
      </div>
    </>
  );
};

/* ---------- scene V1: every branch has its own booking link; no account needed ---------- */

const BRANCHES = [
  {accent: BLUE, txt: TXT_BLUE},
  {accent: ORANGE, txt: TXT_ORANGE},
  {accent: TEAL, txt: TXT_TEAL},
];

const Branches: React.FC<{f: number}> = ({f}) => {
  // Every(0) hospital(1) branch(2) has(3) its(4) own(5) booking(6) link(7) No(8) account(9) needed(10)
  const w = (n: number) => wordF(2, n);
  const tileAt = [w(2), w(4), w(5)];
  const linkAt = [w(6), w(6) + 7, w(7)];
  const noAcc = enter(f, w(8), 10);
  const cross = clamp01((f - w(9)) / 8);
  return (
    <>
      {BRANCHES.map((b, k) => {
        const t = enter(f, tileAt[k], 10);
        const lk = back(enter(f, linkAt[k], 12));
        return (
          <Card key={k} style={{top: 424 + k * 168, height: 148, opacity: t, transform: rise(t)}}>
            <div style={{position: 'absolute', left: 30, top: 30, display: 'flex', alignItems: 'center', gap: 26}}>
              <Tile color={b.accent} size={84} radius={26}>
                <Glyph name="building" size={54} stroke={2.2} />
              </Tile>
              <div style={{display: 'flex', flexDirection: 'column', gap: 14}}>
                <Bar w={330} h={24} />
                <Bar w={220} h={18} color="#E3E8F0" />
              </div>
            </div>
            {/* this branch's own link chip: drawn, no text, drawn as part of the tile itself */}
            <div style={{position: 'absolute', right: 30, top: 38, display: 'flex', alignItems: 'center', gap: 14, height: 72, padding: '0 22px', borderRadius: 36, border: `5px solid ${b.accent}`, background: WHITE, opacity: lk, transform: `scale(${0.7 + 0.3 * lk})`}}>
              <Glyph name="link" size={38} color={b.txt} stroke={2.6} />
              <Bar w={96} h={20} color={b.accent} />
            </div>
          </Card>
        );
      })}
      <div style={{position: 'absolute', left: COL_L, width: COL_W, top: 948, display: 'flex', justifyContent: 'center', opacity: noAcc, transform: rise(noAcc)}}>
        <div style={{display: 'flex', alignItems: 'center', gap: 22, background: WHITE, border: `4px solid ${LINE}`, borderRadius: 54, padding: '14px 40px 14px 18px', boxShadow: '0 12px 28px rgba(26,80,160,0.16)'}}>
          <div style={{position: 'relative', width: 84, height: 84}}>
            <Tile color={BLUE} size={84} radius={42}>
              <Glyph name="user" size={52} stroke={2.4} />
            </Tile>
            <div style={{position: 'absolute', right: -8, bottom: -8, width: 40, height: 40, borderRadius: 20, background: GREEN, border: `4px solid ${WHITE}`, boxSizing: 'border-box', display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: cross, transform: `scale(${0.5 + 0.5 * cross})`}}>
              <Glyph name="check" size={22} stroke={3.6} />
            </div>
          </div>
          <div style={{fontSize: 46, fontWeight: 900, color: INK, whiteSpace: 'nowrap'}}>No account needed</div>
        </div>
      </div>
    </>
  );
};

/* ---------- scene V2: pick a day (up to 60 days ahead), see only the times the hospital has set ---------- */

