export const MegaNetBookingAd: React.FC<{debug?: string}> = ({debug = ''}) => {
  const frame = useCurrentFrame();
  return (
    <DebugContext.Provider value={debug}>
      <AbsoluteFill style={{fontFamily: FONT, backgroundColor: '#EAF3FF'}}>
        {debug === 'notext' && <style>{'*{color:transparent!important;-webkit-text-fill-color:transparent!important;text-shadow:none!important}'}</style>}
        <Sequence from={LEAD} layout="none">
          <Audio src={staticFile('voiceover-booking.mp3')} />
        </Sequence>
        {/* everything visual is frozen once the voice has ended: the last 2s are one held frame */}
        <Freeze frame={Math.min(frame, FREEZE)}>
          <Backgrounds />
          <SceneFrame i={0}>{(f) => <Hook f={f} />}</SceneFrame>
          <SceneFrame i={1}>{(f) => <Branches f={f} />}</SceneFrame>
          <SceneFrame i={2}>{(f) => <Days f={f} />}</SceneFrame>
          <SceneFrame i={3}>{(f) => <Booked f={f} />}</SceneFrame>
          <SceneFrame i={4} header={false}>{(f) => <Cta f={f} />}</SceneFrame>
          <Captions />
          <Violate />
          <ViolateText />
          <CaptionViolation />
        </Freeze>
        {(debug === 'audit' || debug === 'audit-violate') && <AuditProbe />}
      </AbsoluteFill>
    </DebugContext.Provider>
  );
};
